const GEMINI_STOPS = ['#4285F4', '#9B72CB', '#D96570'];

const MONOGRAM_COLORS = ['#4F46E5', '#0EA5E9', '#059669', '#D97706', '#DC2626', '#7C3AED', '#0891B2', '#DB2777'];

// 站点 vendor 名称 → 品牌。优先按厂商判定，模型名只做兜底。
const VENDOR_RULES: Array<[string[], ModelBrand]> = [
  [['openai', 'open ai', 'gpt'], 'openai'],
  [['anthropic', 'claude'], 'claude'],
  [['google', '谷歌', 'gemini', 'deepmind'], 'gemini'],
  [['deepseek', '深度求索'], 'deepseek'],
  [['通义', '阿里', 'alibaba', 'qwen', 'wanx', '万相'], 'qwen'],
  [['智谱', 'zhipu', 'glm', 'z.ai'], 'zhipu'],
  [['moonshot', '月之暗面', 'kimi'], 'kimi'],
  [['字节', 'bytedance', 'doubao', '豆包', 'volc', '火山'], 'doubao'],
  [['meta', 'llama'], 'meta'],
  [['mistral'], 'mistral'],
  [['xai', 'x.ai', 'grok'], 'xai'],
  [['minimax', '稀宇'], 'minimax'],
  [['百度', 'baidu', '文心', 'ernie', 'wenxin'], 'wenxin'],
  [['讯飞', 'iflytek', 'spark', '星火'], 'iflytek'],
  [['腾讯', 'tencent', '混元', 'hunyuan'], 'hunyuan'],
  [['百川', 'baichuan'], 'baichuan'],
  [['阶跃', 'stepfun'], 'stepfun'],
  [['vidu', '生数'], 'vidu'],
  [['suno'], 'suno'],
  [['美团', 'meituan', 'longcat', '龙猫'], 'longcat'],
  [['小米', 'xiaomi', 'mimo'], 'xiaomi'],
];

// 模型名自带品牌前缀时以名称为准（如 deepseek-r1-distill-qwen 仍属 DeepSeek），
// 否则再按站点厂商判定。这样 speech-01-hd 这类名称不含厂商的模型会走 vendor。
const NAME_PREFIX_RULES: Array<[RegExp, ModelBrand]> = [
  [/^deepseek/i, 'deepseek'],
  [/^claude/i, 'claude'],
  [/^gemini|^gemma|^imagen|^veo/i, 'gemini'],
  [/^gpt|^o[1-9](\b|-)|^chatgpt|^dall-e|^whisper|^tts-|^text-embedding/i, 'openai'],
  [/^qwen|^qwq|^qvq|^wanx|^wand|^wan-|^gte/i, 'qwen'],
  [/^glm|^cogview|^cogvideo/i, 'zhipu'],
  [/^kimi|^moonshot/i, 'kimi'],
  [/^doubao|^seedream|^seed/i, 'doubao'],
  [/^ernie|^wenxin/i, 'wenxin'],
  [/^spark|^iflytek/i, 'iflytek'],
  [/^hy[-\d]|^hunyuan/i, 'hunyuan'],
  [/^minimax|^abab|^hailuo|^speech|^asr-|^music-|^image-01/i, 'minimax'],
  [/^baichuan/i, 'baichuan'],
  [/^step[-\d]|^stepfun/i, 'stepfun'],
  [/^vidu/i, 'vidu'],
  [/^suno/i, 'suno'],
  [/^longcat/i, 'longcat'],
  [/^mimo/i, 'xiaomi'],
  [/^llama/i, 'meta'],
  [/^mistral|^mixtral|^codestral/i, 'mistral'],
  [/^grok/i, 'xai'],
];

const NAME_CONTAINS_RULES: Array<[RegExp, ModelBrand]> = [
  [/deepseek/i, 'deepseek'],
  [/claude/i, 'claude'],
  [/gemini/i, 'gemini'],
  [/qwen/i, 'qwen'],
  [/glm/i, 'zhipu'],
  [/kimi/i, 'kimi'],
  [/doubao|豆包/i, 'doubao'],
  [/ernie|文心/i, 'wenxin'],
  [/spark/i, 'iflytek'],
  [/hunyuan|混元/i, 'hunyuan'],
  [/minimax|hailuo/i, 'minimax'],
  [/baichuan/i, 'baichuan'],
  [/vidu/i, 'vidu'],
  [/suno/i, 'suno'],
  [/longcat/i, 'longcat'],
  [/xiaomi|mimo|小米/i, 'xiaomi'],
  [/llama/i, 'meta'],
  [/mistral|mixtral|codestral/i, 'mistral'],
  [/grok/i, 'xai'],
];

export function modelBrand(name: string, vendor?: string): ModelBrand | null {
  const modelKey = (name ?? '').toLowerCase();
  for (const [pattern, brand] of NAME_PREFIX_RULES) {
    if (pattern.test(modelKey)) return brand;
  }
  const vendorKey = (vendor ?? '').toLowerCase().trim();
  if (vendorKey) {
    for (const [keys, brand] of VENDOR_RULES) {
      if (keys.some((key) => vendorKey.includes(key))) return brand;
    }
  }
  for (const [pattern, brand] of NAME_CONTAINS_RULES) {
    if (pattern.test(modelKey)) return brand;
  }
  return null;
}

function monogramText(name: string, vendor?: string) {
  const source = (vendor || name || '?').trim();
  const latin = source.match(/[A-Za-z]/);
  if (latin && /^[\x00-\x7F]+$/.test(source)) return source.slice(0, 1).toUpperCase();
  return source.slice(0, 1);
}

function monogramColor(seed: string) {
  let hash = 0;
  for (let i = 0; i < seed.length; i += 1) {
    hash = (hash * 31 + seed.charCodeAt(i)) % 100000;
  }
  return MONOGRAM_COLORS[hash % MONOGRAM_COLORS.length];
}

export function ModelLogo({
  name,
  vendor,
  size = 30,
}: {
  name: string;
  vendor?: string;
  size?: number;
}) {
  const brand = modelBrand(name, vendor);
  const gradientId = `logo-${useId().replace(/[^a-zA-Z0-9]/g, '')}`;
  const dark = useScheme() === 'dark';
  const mono = dark ? '#F5F5F7' : '#111111';

  if (!brand) {
    const label = monogramText(name, vendor);
    const bg = monogramColor(vendor || name);
    return (
      <Svg width={size} height={size} viewBox="0 0 24 24">
        <Rect x={0} y={0} width={24} height={24} rx={6} fill={bg} />
        <SvgText
          x={12}
          y={16.6}
          fill="#FFFFFF"
          fontSize={label.length > 1 ? 9 : 12}
          fontWeight="600"
          textAnchor="middle"
        >
          {label}
        </SvgText>
      </Svg>
    );
  }

  const art = brandArt[brand];
  return (
    <Svg width={size} height={size} viewBox="0 0 24 24">
      {brand === 'gemini' ? (
        <>
          <Defs>
            <LinearGradient id={gradientId} x1="0" y1="0" x2="1" y2="1">
              {GEMINI_STOPS.map((color, index) => (
                <Stop key={color} offset={index / (GEMINI_STOPS.length - 1)} stopColor={color} />
              ))}
            </LinearGradient>
          </Defs>
          <Path d={art.layers[0].d} fill={`url(#${gradientId})`} />
        </>
      ) : (
        <>
          {art.gradients && art.gradients.length > 0 ? (
            <Defs>
              {art.gradients.map((gradient, index) => (
                <LinearGradient
                  key={`${gradientId}-${index}`}
                  id={`${gradientId}-${index}`}
                  x1={gradient.x1}
                  y1={gradient.y1}
                  x2={gradient.x2}
                  y2={gradient.y2}
                  gradientUnits={gradient.units === 'user' ? 'userSpaceOnUse' : 'objectBoundingBox'}
                >
                  {gradient.stops.map((color, stopIndex) => (
                    <Stop
                      key={color + stopIndex}
                      offset={stopIndex / Math.max(gradient.stops.length - 1, 1)}
                      stopColor={color}
                    />
                  ))}
                </LinearGradient>
              ))}
            </Defs>
          ) : null}
          {art.layers.map((layer, index) => {
            const fill = layer.fill.startsWith('@')
              ? `url(#${gradientId}-${layer.fill.slice(1)})`
              : layer.fill === 'currentColor'
                ? mono
                : layer.fill;
            return <Path key={`${brand}-${index}`} d={layer.d} fill={fill} />;
          })}
        </>
      )}
    </Svg>
  );
}
